CREATE TABLE finance_entries(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('ingreso','gasto')),society_id bigint NOT NULL REFERENCES societies(id),occurred_on date NOT NULL,category text NOT NULL CHECK(length(trim(category)) BETWEEN 2 AND 100),description text NOT NULL DEFAULT '',amount_cents bigint NOT NULL CHECK(amount_cents>0),method text NOT NULL DEFAULT 'Efectivo',status text NOT NULL CHECK(status IN ('registrado','pendiente','aprobado','rechazado','pagado')),created_by bigint NOT NULL REFERENCES users(id),approved_by bigint REFERENCES users(id),paid_by bigint REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),decided_at timestamptz,paid_at timestamptz, CHECK(approved_by IS NULL OR approved_by<>created_by), CHECK(kind='gasto' OR (approved_by IS NULL AND paid_by IS NULL)));
CREATE TABLE finance_accounts(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name text NOT NULL UNIQUE,kind text NOT NULL CHECK(kind IN ('caja','banco')),active boolean NOT NULL DEFAULT true);
CREATE TABLE finance_postings(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,entry_id bigint NOT NULL UNIQUE REFERENCES finance_entries(id) ON DELETE RESTRICT,account_id bigint NOT NULL REFERENCES finance_accounts(id),direction smallint NOT NULL CHECK(direction IN (-1,1)),amount_cents bigint NOT NULL CHECK(amount_cents>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE finance_budgets(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,society_id bigint NOT NULL REFERENCES societies(id),year int NOT NULL CHECK(year BETWEEN 2000 AND 2200),month int NOT NULL CHECK(month BETWEEN 1 AND 12),amount_cents bigint NOT NULL CHECK(amount_cents>=0),UNIQUE(society_id,year,month));
CREATE TABLE sermon_outlines(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,item_id bigint NOT NULL UNIQUE REFERENCES weekly_items(id) ON DELETE CASCADE,title text NOT NULL,base_text text NOT NULL DEFAULT '',introduction text NOT NULL DEFAULT '',point_one text NOT NULL DEFAULT '',point_two text NOT NULL DEFAULT '',point_three text NOT NULL DEFAULT '',application text NOT NULL DEFAULT '',conclusion text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now());
