INSERT INTO finance_accounts(name,kind) VALUES('Caja General','caja') ON CONFLICT DO NOTHING;
INSERT INTO permissions(code) VALUES('finance.read'),('finance.record'),('finance.approve'),('finance.pay'),('finance.budget'),('outline.read'),('outline.write') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_code) SELECT r.id,p.code FROM roles r JOIN permissions p ON p.code IN ('finance.read','finance.record','finance.approve','finance.pay','finance.budget','outline.read','outline.write') WHERE r.name='Administrador' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_code) SELECT r.id,p.code FROM roles r JOIN permissions p ON p.code IN ('outline.read','outline.write') WHERE r.name='Secretaría' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_code) SELECT r.id,p.code FROM roles r JOIN permissions p ON p.code='outline.read' WHERE r.name='Consulta' ON CONFLICT DO NOTHING;
INSERT INTO roles(name) VALUES('Finanzas Registro'),('Finanzas Aprobación'),('Finanzas Pagos') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_code) SELECT r.id,p.code FROM roles r JOIN permissions p ON (r.name='Finanzas Registro' AND p.code IN ('finance.read','finance.record')) OR (r.name='Finanzas Aprobación' AND p.code IN ('finance.read','finance.approve')) OR (r.name='Finanzas Pagos' AND p.code IN ('finance.read','finance.pay')) ON CONFLICT DO NOTHING;
